package org.ramki.chatemoji.enums;

public enum Emojis {

    DEF_SMILE("smile", ""),
    DEF_SAD("sad", ""),
    DEF_SOB("sob", ""),
    DEF_PENSIVE("pensive", ""),
    DEF_CRIMACE("grimace", ""),
    DEF_SKULL("skull", "");

    private String key;
    private String value;

    private Emojis(String key, String value) {
        this.key = key;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public String getValue() {
        return value;
    }
}
